#!/usr/bin/env python3
# reserve_L13e.py — 새 과 L13e(무기고의 깃발 맞추기 · 세계 s13 의 e) — 면역 세계 「성 방어전」의 다섯째 장(B 세포 · 항원결정부위 · V(D)J 재배열 · 클론선택 · 형질세포와 기억세포 · 1차 · 2차 반응 · 배중심 · 단클론 항체 · 하이브리도마).
#  L13c 부터의 방식 — 「성의 내성(둥근 돌탑) 무기고에 처음 보는 세균이 끌려온 날」 한 장면(Gemini 가 통째로 그림 + 구역 편집 + PIL).
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
B = '[2026-11-15 새 과 L13e]'
new = {
 '슬롯머신 둘 — 큰 것은 릴 셋 · 작은 것은 릴 둘(두 손잡이를 함께 당기는 벌)': f'항체 다양성의 유전자 재배열(V(D)J 재조합 — 항원을 만나기 전에 무작위로 조각을 골라 이음) + 조합 수(중쇄 V × D × J × 경쇄 V × J) 전용 {B} — L13e s3 · s4. 릴 셋 = 중쇄의 V · D · J · 릴 둘 = 경쇄의 V · J · 두 손잡이를 함께 = 중쇄와 경쇄의 짝까지 곱한다. ⚠ 동전을 넣지 않는다(【동전】 = ATP) · 릴 그림은 도형만(숫자 · 글자 · 과일 없음 — Gemini 가 큰 기계 가운데 줄을 별 셋으로 맞춰 「당첨」처럼 그렸다). ⚠ 처음 바탕은 작은 기계도 릴 셋 · 벌의 팔이 셋이 되어 구역 편집 Z3b · Z3c 로 고쳤다.',
 '미리 만든 깃발이 빼곡한 나무 걸이(별 · 세모 · 동그라미 · 네모 · 마름모 무늬가 제각각)': f'항원을 만나기 전에 이미 갖춰진 다양한 수용체의 풀(클론선택설 — 특이성은 노출 전에 정해진다 · 주형설은 틀림) 전용 {B} — L13e s3.',
 '세균 몸에 돋은 도형 돌기 셋(머리의 노란 별 · 파란 세모 뿔 · 분홍 동그라미) + 같은 도형의 깃발만 닿아 튀는 불똥': f'항원결정부위(에피토프 — 수용체가 붙는 항원의 한 부분 · 한 항원에 여럿) · 특이성 전용 {B} — L13e s2. 벌이 손에 든 제 깃발 = BCR(막에 붙은 항체 — 던지는 깃발은 분비된 항체). ⚠ 열쇠 · 자물쇠 꼴로 그리지 않는다(【금색 자물쇠】 · 【자물쇠의 색과 열쇠구멍 모양】) · 하트(성) · 초승달(CAM) 도형을 쓰지 않는다. ⚠ 파란 세모는 Gemini 가 원뿔(깔때기)로 그려 「세모 뿔」로 적었다 · 처음 바탕은 돌기가 여섯(같은 것 둘씩)이라 셋으로 고쳤다(구역 편집 Z1). 창에 다시 온 세균도 같은 돌기 셋(Z7 — 다르면 「같은 세균」이 흔들린다 · 일치 검사 1회).',
 '바닥의 밝은 빛 동그라미(내성 무기고 천장 채광창이 던진 빛)': f'배중심(림프소포 가운데의 밝은 자리 — 선택된 B 가 증식하고 과돌연변이 · 2차 반응의 항체 합성 = 림프조직이지 혈액이 아니다) 전용 {B} — L13e s5 · s6 · s10. ⚠ 「배중심 = 배(과일)」로 그리지 않는다(【윗동이 열린 큰 연두색 배(과일)…】 = 배아줄기세포). 진홍 호스(혈관)는 다 만든 깃발을 나를 뿐.',
 '부챗살처럼 겹쳐 솟는 똑같은 별 깃발 벌 여럿': f'클론 증식(클론선택 — 맞는 림프구만 골라져 증식 · 분화, 세포고사가 아니다) 전용 {B} — L13e s5. ⚠ 처음 바탕은 벌 하나가 깃발 일곱을 부채처럼 든 꼴이라 「벌 여럿」으로 구역 편집(Z2 — 가로로 긴 오림은 Gemini 가 틀을 다시 짜 16:9 로 다시 오림 Z2b).',
 '앉은 벌이 깃대를 쥔 채 작은 쇠줄로 깃발 천을 감(불똥) · 깃대는 그대로': f'체세포 과돌연변이(가변부위 V 에만 — C 불변부위 아님) 전용 {B} — L13e s6. 깃발 천 = V · 깃대 = C. ⚠ 처음 바탕의 도구가 가위로 보여(【가위】 예약) 납작한 쇠줄로 · 깃대 없는 천 조각이라 깃대를 쥐게(Z6).',
 '진홍 호스 위의 둥근 뚜껑 구멍에 똑같은 별 깃발을 밀어 넣는 벌 + 태엽이 멎어 소용돌이 눈으로 깃발 더미에 벌렁 누운 벌': f'효과세포(형질세포) — 한 종류 항체만 · 단명(기억세포와 별개) 전용 {B} — L13e s7. 똑같은 별 깃발 = 단일 특이성 · 멎은 태엽 = 짧은 수명 · 호스에 넣음 = 항체가 혈액으로. ⚠ 처음 바탕은 바닥 뚜껑(트랩도어) 밑으로 호스가 지나 「바닥 구멍에 넣는다」로 읽힐 수 있어 호스 자체의 둥근 뚜껑 구멍으로(Z4).',
 '흰 수염이 침대 밖으로 늘어질 만큼 자란 채 두꺼운 빨간 책을 안고 자거나 읽는 벌들(이층 침대)': f'기억세포 — 장수 · 같은 항원의 재감염에 대비 · 2차 반응에서 곧장 형질세포로(창으로 다시 온 같은 세균을 깃발 산으로 묻음) 전용 {B} — L13e s8 · s9. 빨간 책 = 기억(L13a 잠옷 병정의 책) · 흰 수염 = 오래 잠. ⚠ 【다리를 곧게 뻗고 앉은 흰 수염 팔순 할아버지 …】(tRNA)와 가른다 — 이쪽은 벌. ⚠ Gemini 가 침대 곁 벽에 「Z.」(잠)을 써서 지웠다.',
 '태엽 벌의 몸에 검은 게의 집게발 · 게 다리가 돋은 괴물(태엽이 저절로 빙빙) + 똑같은 별 깃발이 가득한 고리버들 바구니': f'하이브리도마(B 세포 + 암세포 융합 — 목적은 불멸화 · 「항체 생산을 돕는다」는 함정) + 단클론 항체(한 클론 · 한 항원결정부위) 전용 {B} — L13e s11. 【작은 검은 게】 = 암 그대로. 배지 없음 = 몸에서 자란 세포가 아니라 실험실에서 만든 것(독자가 「편이 불분명」이라 했다 — 말로 밝힘). ⚠ 바구니에 다른 무늬 깃발이 섞이면 ✕(일치 검사 1회 → Z5). 뒤쪽 반을 게 몸통으로 그려 달랬지만 Gemini 는 벌 몸에 집게발 · 다리만 달았다 — 글을 그림에 맞춤.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('장난감 벌(노란 벌)', f'★ {B} 무기고의 벌들 — 손에 든 제 깃발 = BCR · 슬롯머신(재배열) · 부챗살 증식(클론) · 쇠줄(과돌연변이) · 호스에 깃발(형질세포) · 수염 · 빨간 책(기억) · 게 집게발 괴물(하이브리도마). 벌의 배지는 몸통 옆(침대 벌은 책 · 수염에 가려 몸이 보이는 것만).')
add('작은 검은 게', f'★ {B} L13e s11 태엽 벌의 몸에 돋은 검은 게 집게발 · 다리 = 하이브리도마의 암세포(불멸) — 벌(B) + 게(암) 융합.')
add('두 줄 단추 병정이 제 눈에 낀 외눈 안경 + 파란 배지로 가는 눈길 점선', f'★ {B} L13e s1 무기고의 한 줄 단추 병정(CD4)도 외눈 안경 = TCR — 맨 세균(날 항원)을 보고 어리둥절(쟁반 없이는 못 본다 · L13c) ↔ 벌(B)은 BCR(손에 든 깃발)로 날 항원에 바로.')
add('잠옷 · 수면 모자 차림으로 장화를 한 짝만 신은 장난감 병정(하품 · 세균 한 놈을 그린 종이 · 팔에 안은 두꺼운 빨간 책 · 발치의 털모자와 장화 한 짝)', f'★ {B} 두꺼운 빨간 책 = 기억 — L13e 이층 침대의 수염 벌(기억 B 세포)도 안았다.')
out = json.dumps(d, ensure_ascii=False, indent=1)
assert json.loads(out) == d
open(P, 'w', encoding='utf-8').write(out)
print('예약', len(R))
